import os, tempfile, pathlib, sys
base = pathlib.Path(tempfile.gettempdir())
print("tempdir:", base)
for name in ("probe-pwsh-made", "probe-py-made"):
    p = base / name
    try:
        p.mkdir(exist_ok=True)
        print(name, "mkdir=ok exists=", p.exists())
    except Exception as e:
        print(name, "mkdir FAIL", type(e).__name__, e)
    try:
        print(name, "scandir ->", [str(x.name) for x in os.scandir(p)])
    except Exception as e:
        print(name, "scandir FAIL", type(e).__name__, e)
    try:
        (p / "child").mkdir(exist_ok=True)
        (p / "child" / "f.txt").write_text("x", encoding="utf-8")
        print(name, "child write ok, listdir:", os.listdir(p))
    except Exception as e:
        print(name, "child op FAIL", type(e).__name__, e)
    try:
        import shutil; shutil.rmtree(p); print(name, "rmtree ok")
    except Exception as e:
        print(name, "rmtree FAIL", type(e).__name__, e)
